      '.mp-pill:focus-visible{outline:var(--dsw-focus-ring-width,2px) solid var(--dsw-focus-ring-color,var(--dsw-alias-state-business-primary,#4176E6));outline-offset:2px}',
      '.mp-pill.is-primary{background:var(--dsw-alias-state-business-primary,#4176E6);border-color:transparent;color:#fff}',
      '.mp-kit-modal{width:min(640px,calc(100vw - 48px))}',
      // The floating player card paints its own dark glass on the always-dark player page
      // (the same dark-surface exception as `.mp-np`, guarded in test/theme.test.mjs), but
      // its controls read the host tokens. In the light theme those resolve to dark ink and
      // near-white layers, so the card ended up with white-on-white tiles, pills and inputs.
      // Pin the tokens it sits on to their dark-theme values for everything inside the card;
      // the surface itself stays on the inline dark glass above.
      '.mp-card{--dsw-alias-label-primary:#f4f4f5;--dsw-alias-label-secondary:#a1a1aa;--dsw-alias-label-tertiary:#8a8a93;--dsw-alias-bg-layer-1:#17171a;--dsw-alias-bg-layer-2:rgba(255,255,255,.06);--dsw-alias-bg-layer-3:rgba(255,255,255,.08);--dsw-alias-border-l1:rgba(255,255,255,.07);--dsw-alias-border-l2:rgba(255,255,255,.14);--dsw-alias-interactive-bg-hover:rgba(255,255,255,.07);--dsw-alias-interactive-bg-active:rgba(255,255,255,.1);color:#f4f4f5}',
      // The card's panes scroll, but a scrollbar appearing for one frame during the tab
      // animation takes width from the content and the layout jumps when it leaves again.
      // Hide it on every scroll container inside the card instead of reserving a gutter.
      '.mp-card-scroll{scrollbar-width:none;-ms-overflow-style:none}',
      '.mp-card-scroll::-webkit-scrollbar{width:0;height:0;display:none}',
      '.mp-card-body-wrap ::-webkit-scrollbar{width:0;height:0;display:none}',
      '.mp-card-body-wrap *{scrollbar-width:none;-ms-overflow-style:none}',
        // The match window draws its own frame: the host layer only provides the modal
      // stack (so it sits above the tag editor), and this makes that layer a full
      // transparent surface instead of a 760px box.
      '.mp-kit-modal.mp-kit-modal-headless.mp-lym-modal{width:100vw;height:100vh;max-width:100vw;max-height:100vh;margin:0;border:0;border-radius:0;background:transparent;box-shadow:none}',
        '.mp-kit-modal.mp-kit-modal-headless.mp-lym-modal .mp-kit-body{padding:0;gap:0;height:100%}',
      '.mp-kit-modal.mp-kit-modal-headless.mp-lym-modal .mp-kit-content{max-height:100%;height:100%;padding:0;overflow:visible}',
      '.mp-lym-layer{position:relative;display:flex;align-items:center;justify-content:center;width:100%;height:100%;padding:24px;box-sizing:border-box}',
      '.mp-lym-layer.is-embedded{padding:0}',
      '.mp-lym-window{position:relative;display:flex;flex-direction:column;width:min(1024px,calc(100vw - 48px));height:min(720px,80vh);max-height:calc(100vh - 48px);min-height:320px;border-radius:var(--dsw-radius-panel,28px);background:var(--dsw-alias-bg-layer-1,#1a1a1e);box-shadow:var(--dsw-elevation-prominent,0 24px 64px rgba(0,0,0,.45));color:var(--dsw-alias-label-primary,#f4f4f5);font-size:13px;line-height:20px;overflow:hidden}',
      '.mp-lym-head{display:flex;align-items:flex-start;gap:12px;padding:16px 24px;border-bottom:.5px solid var(--dsw-alias-border-l3,#ffffff1a);flex:0 0 auto}',
