        artists: t('v2.artists'),
        folders: t('v2.folders'),
        favorites: t('v2.favorites'),
        playlists: t('v2.playlists'),
        stats: t('v2.stats'),
        recent: t('v2.recent'),
        discover: t('p3.discover'),
        cloud: t('p3.cloud'),
